begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.entitlements(school_id,code,enabled,effective_from)select id,'portfolio',true,'2026-09-01'from app.schools on conflict(school_id,code)do update set enabled=true;
create temporary table asset_fixture(id uuid,receipt jsonb);grant select,insert,update on asset_fixture to cuevo_api;
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into asset_fixture(receipt)select internal.asset_command('stage',null,'{"ownerId":"20000000-0000-4000-8000-000000000012","name":"work.txt","contentType":"text/plain","byteSize":20,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','asset-stage-golden-001',repeat('a',64),'asset-request');update asset_fixture set id=(receipt->>'id')::uuid;
select throws_ok($$select internal.asset_command('stage',null,'{"ownerId":"20000000-0000-4000-8000-000000000012","name":"large.txt","contentType":"text/plain","byteSize":524289,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','asset-stage-large-001',repeat('b',64),'asset-request')$$,'22023',null,'new staged file bounded to512KiB');
select throws_ok($$select internal.asset_command('finalize',(select id from asset_fixture),'{"byteSize":20,"sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"}','asset-finalize-wrong-001',repeat('b',64),'asset-request')$$,'22023',null,'finalize mismatched checksum denied');
select internal.asset_command('finalize',(select id from asset_fixture),'{"byteSize":20,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','asset-finalize-golden-001',repeat('c',64),'asset-request');
select internal.asset_command('finalize',(select id from asset_fixture),'{"byteSize":20,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','asset-finalize-newkey-001',repeat('c',64),'asset-request');
select internal.asset_command('retire',(select id from asset_fixture),'{"reason":"School reviewed retirement","confirmRetirement":true}','asset-retire-golden-001',repeat('d',64),'asset-request');
select throws_ok($$select internal.asset_command('finalize',(select id from asset_fixture),'{"byteSize":20,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','asset-finalize-golden-001',repeat('c',64),'asset-replay')$$,'22023',null,'retired source cannot replay available finalize');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select is((select count(*)from app.private_assets where id=(select id from asset_fixture)),0::bigint,'parent cannot read raw private learner asset');
reset role;
select is((select count(*)from internal.audit_events where action='asset.finalize'and entity_id=(select id from asset_fixture)),1::bigint,'new-key finalize creates one canonical audit');
select is((select count(*)from internal.outbox_events where type='asset.updated'and entity_id=(select id from asset_fixture)and deduplication_key='asset:finalize:'||(select id::text from asset_fixture)),1::bigint,'new-key finalize creates one canonical event');
select throws_ok($$update app.private_assets set sha256=repeat('b',64)where id=(select id from asset_fixture)$$,'55000',null,'metadata checksum immutable');
select ok((select public is false from storage.buckets where id='learner-private'),'learner byte bucket private');
select ok(not has_table_privilege('authenticated','app.private_assets','SELECT,INSERT,UPDATE,DELETE'),'browser has no direct asset metadata grants');
select*from finish();rollback;
